export function docCloseArgv(opts: { id?: string; year?: string; doc?: string; intent: string; sync?: boolean; }): string[] {
  const argv = ["doc", "close"];
  option(argv, "--id", opts.id);
  option(argv, "--year", opts.year);
  option(argv, "--doc", opts.doc);
  argv.push("--intent", value(opts.intent, "doc close", "intent"));
  if (opts.sync) argv.push("--sync");
  argv.push("--json");
  return argv;
}

